#include "wire.hpp"
#include <bit>
#include <cerrno>
#include <cmath>
#include <cstring>
#include <limits>
#include <poll.h>
#include <stdexcept>
#include <unistd.h>
#include <time.h>

namespace ab {
namespace {
void put16(std::vector<uint8_t>& b,uint16_t v){b.push_back(uint8_t(v));b.push_back(uint8_t(v>>8));}
void put32(std::vector<uint8_t>& b,uint32_t v){for(int i=0;i<4;i++)b.push_back(uint8_t(v>>(8*i)));}
void put64(std::vector<uint8_t>& b,uint64_t v){for(int i=0;i<8;i++)b.push_back(uint8_t(v>>(8*i)));}
uint16_t get16(const uint8_t*p){return uint16_t(p[0])|uint16_t(p[1])<<8;}
uint32_t get32(const uint8_t*p){uint32_t v=0;for(int i=0;i<4;i++)v|=uint32_t(p[i])<<(8*i);return v;}
uint64_t get64(const uint8_t*p){uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(p[i])<<(8*i);return v;}
int64_t geti64(const uint8_t*p){return std::bit_cast<int64_t>(get64(p));}
bool valid_utf8(const uint8_t*p,size_t n){for(size_t i=0;i<n;){uint8_t a=p[i++];if(a<0x80)continue;uint32_t cp=0;size_t more=0;if(a>=0xc2&&a<=0xdf){cp=a&0x1f;more=1;}else if(a>=0xe0&&a<=0xef){cp=a&0x0f;more=2;}else if(a>=0xf0&&a<=0xf4){cp=a&0x07;more=3;}else return false;if(i+more>n)return false;for(size_t j=0;j<more;j++){uint8_t b=p[i++];if((b&0xc0)!=0x80)return false;cp=(cp<<6)|(b&0x3f);}if((more==2&&cp<0x800)||(more==3&&cp<0x10000)||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))return false;}return true;}
void append_floats(std::vector<uint8_t>& b,const std::array<float,160>& samples){for(float f:samples){if(!std::isfinite(f))throw std::runtime_error("non-finite audio");put32(b,std::bit_cast<uint32_t>(f));}}
std::array<float,160> read_floats(const uint8_t*p){std::array<float,160>a{};for(size_t i=0;i<a.size();i++){a[i]=std::bit_cast<float>(get32(p+4*i));if(!std::isfinite(a[i]))throw std::runtime_error("non-finite audio");}return a;}
int64_t monotonic_ms(){timespec t{};if(clock_gettime(CLOCK_MONOTONIC,&t)!=0)throw std::runtime_error("monotonic clock failed");return int64_t(t.tv_sec)*1000+t.tv_nsec/1000000;}
void wait_fd(int fd,short events,int64_t deadline){pollfd p{fd,events,0};for(;;){int64_t remaining=deadline-monotonic_ms();if(remaining<=0)throw std::runtime_error("IPC absolute deadline exceeded");int r=poll(&p,1,remaining>INT32_MAX?INT32_MAX:int(remaining));if(r<0&&errno==EINTR)continue;if(r==0)throw std::runtime_error("IPC absolute deadline exceeded");if(r<0)throw std::runtime_error("poll failed");if(p.revents&(POLLERR|POLLNVAL))throw std::runtime_error("IPC descriptor error");if(p.revents&(events|POLLHUP))return;}}
void read_exact(int fd,uint8_t*out,size_t n,int64_t deadline){size_t done=0;while(done<n){wait_fd(fd,POLLIN,deadline);ssize_t got=::read(fd,out+done,n-done);if(got<0&&errno==EINTR)continue;if(got<0&&(errno==EAGAIN||errno==EWOULDBLOCK))continue;if(got<=0)throw std::runtime_error("IPC EOF/truncation");done+=size_t(got);}}
void write_exact(int fd,const uint8_t*data,size_t n,int64_t deadline){size_t done=0;while(done<n){wait_fd(fd,POLLOUT,deadline);ssize_t got=::write(fd,data+done,n-done);if(got<0&&errno==EINTR)continue;if(got<0&&(errno==EAGAIN||errno==EWOULDBLOCK))continue;if(got<=0)throw std::runtime_error("IPC write failed");done+=size_t(got);}}
Message parse_header(const std::array<uint8_t,24>&h){if(get32(h.data())!=kMagic||get16(h.data()+4)!=kVersion)throw std::runtime_error("bad IPC magic/version");uint16_t type=get16(h.data()+6);if(type<1||type>9)throw std::runtime_error("unknown IPC message type");uint32_t n=get32(h.data()+8),stream=get32(h.data()+12);if(n>kMaxPayload||stream>=64)throw std::runtime_error("IPC length/stream out of bounds");return {static_cast<Type>(type),stream,get64(h.data()+16),{}};}
void validate_payload(const Message&m){size_t n=m.payload.size();switch(m.type){case Type::Prepare:if(n<36||n>36+61440||get32(m.payload.data()+32)!=n-36||!valid_utf8(m.payload.data()+36,n-36))throw std::runtime_error("invalid PREPARE size/UTF-8");break;case Type::Ready:if(n!=64)throw std::runtime_error("invalid READY size");break;case Type::Input:if(n!=668)throw std::runtime_error("invalid INPUT size");(void)decode_input(m);break;case Type::Output:if(n!=692)throw std::runtime_error("invalid OUTPUT size");(void)decode_output(m);break;case Type::EndInput:case Type::Drained:case Type::Reset:if(n!=16)throw std::runtime_error("invalid epoch/end size");break;case Type::Error:if(n<16||get32(m.payload.data()+12)!=n-16||get32(m.payload.data()+12)>kMaxPayload-16||get32(m.payload.data()+8)>10||!valid_utf8(m.payload.data()+16,n-16))throw std::runtime_error("invalid ERROR size/status/UTF-8");break;case Type::Close:if(n!=0)throw std::runtime_error("CLOSE must be empty");break;}}
}
std::vector<uint8_t> encode_message(const Message&m){if(m.stream>=64||m.payload.size()>kMaxPayload)throw std::runtime_error("message bound exceeded");std::vector<uint8_t>b;b.reserve(24+m.payload.size());put32(b,kMagic);put16(b,kVersion);put16(b,static_cast<uint16_t>(m.type));put32(b,static_cast<uint32_t>(m.payload.size()));put32(b,m.stream);put64(b,m.sequence);b.insert(b.end(),m.payload.begin(),m.payload.end());validate_payload(m);return b;}
Message read_message(int fd,int timeout){int64_t deadline=monotonic_ms()+timeout;std::array<uint8_t,24>h{};read_exact(fd,h.data(),h.size(),deadline);Message m=parse_header(h);m.payload.resize(get32(h.data()+8));if(!m.payload.empty())read_exact(fd,m.payload.data(),m.payload.size(),deadline);validate_payload(m);return m;}
void write_message(int fd,const Message&m,int timeout){int64_t deadline=monotonic_ms()+timeout;auto bytes=encode_message(m);write_exact(fd,bytes.data(),bytes.size(),deadline);}
Message prepare(uint32_t s,uint64_t q,const std::array<uint8_t,32>&d,const std::string&c){if(c.empty()||c.size()>61440)throw std::runtime_error("config bound");std::vector<uint8_t>p(d.begin(),d.end());put32(p,uint32_t(c.size()));p.insert(p.end(),c.begin(),c.end());return {Type::Prepare,s,q,std::move(p)};}
Message ready(uint32_t s,uint64_t q,const std::array<uint8_t,32>&b,const std::array<uint8_t,32>&d){std::vector<uint8_t>p(b.begin(),b.end());p.insert(p.end(),d.begin(),d.end());return {Type::Ready,s,q,std::move(p)};}
Message input_message(uint32_t s,uint64_t q,const Input&i){if(i.valid>160||((i.flags&1)?(i.valid==0||i.valid>=160):i.valid!=160)||(i.flags&~1u))throw std::runtime_error("invalid INPUT metadata");if(i.flags&1)for(size_t k=i.valid;k<160;k++)if(i.samples[k]!=0)throw std::runtime_error("nonzero final input padding");std::vector<uint8_t>p;put64(p,i.epoch);put64(p,std::bit_cast<uint64_t>(i.first));put32(p,i.valid);put32(p,i.flags);put32(p,0);append_floats(p,i.samples);return {Type::Input,s,q,std::move(p)};}
Input decode_input(const Message&m){if(m.type!=Type::Input||m.payload.size()!=668)throw std::runtime_error("not INPUT");const auto*p=m.payload.data();Input i{get64(p),geti64(p+8),get32(p+16),get32(p+20),read_floats(p+28)};if(get32(p+24)!=0||i.valid>160||((i.flags&1)?(i.valid==0||i.valid>=160):i.valid!=160)||(i.flags&~1u))throw std::runtime_error("invalid INPUT metadata/reserved");if(i.flags&1)for(size_t k=i.valid;k<160;k++)if(i.samples[k]!=0)throw std::runtime_error("nonzero final input padding");return i;}
Message output_message(uint32_t s,uint64_t q,const Output&o){if(o.produced>160||o.valid_offset>o.produced||o.valid>o.produced-o.valid_offset||(o.flags&~7u)||o.phase>1||(o.flags&4u&&o.valid!=0)||o.service_begin<0||o.service_end<0||(o.service_end&&o.service_begin>o.service_end))throw std::runtime_error("invalid OUTPUT metadata");std::vector<uint8_t>p;put64(p,o.epoch);put64(p,std::bit_cast<uint64_t>(o.source_first));put32(p,o.produced);put32(p,o.valid_offset);put32(p,o.valid);put32(p,o.flags);put32(p,o.phase);put64(p,std::bit_cast<uint64_t>(o.service_begin));put64(p,std::bit_cast<uint64_t>(o.service_end));append_floats(p,o.samples);return {Type::Output,s,q,std::move(p)};}
Output decode_output(const Message&m){if(m.type!=Type::Output||m.payload.size()!=692)throw std::runtime_error("not OUTPUT");const auto*p=m.payload.data();Output o{get64(p),geti64(p+8),get32(p+16),get32(p+20),get32(p+24),get32(p+28),get32(p+32),geti64(p+36),geti64(p+44),read_floats(p+52)};if(o.produced>160||o.valid_offset>o.produced||o.valid>o.produced-o.valid_offset||(o.flags&~7u)||o.phase>1||(o.flags&4u&&o.valid!=0)||o.service_begin<0||o.service_end<0||(o.service_end&&o.service_begin>o.service_end))throw std::runtime_error("invalid OUTPUT metadata");return o;}
Message end_message(Type t,uint32_t s,uint64_t q,const End&e){if(t!=Type::EndInput&&t!=Type::Drained&&t!=Type::Reset)throw std::runtime_error("invalid end message type");std::vector<uint8_t>p;put64(p,e.epoch);put64(p,std::bit_cast<uint64_t>(e.sample));return {t,s,q,std::move(p)};}
End decode_end(const Message&m){if((m.type!=Type::EndInput&&m.type!=Type::Drained&&m.type!=Type::Reset)||m.payload.size()!=16)throw std::runtime_error("invalid epoch/end message");return {get64(m.payload.data()),geti64(m.payload.data()+8)};}
Message error_message(uint32_t s,uint64_t q,uint64_t epoch,int32_t status,const std::string&text){if(status<0||status>10||text.size()>kMaxPayload-16)throw std::runtime_error("ERROR bounds");std::vector<uint8_t>p;put64(p,epoch);put32(p,std::bit_cast<uint32_t>(status));put32(p,uint32_t(text.size()));p.insert(p.end(),text.begin(),text.end());return {Type::Error,s,q,std::move(p)};}
std::array<uint8_t,32> digest_from_hex(const std::string&h){if(h.size()!=64)throw std::runtime_error("SHA-256 must have 64 hex characters");std::array<uint8_t,32>d{};auto cv=[](char c)->int{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;throw std::runtime_error("invalid lowercase SHA-256 hex");};for(size_t i=0;i<32;i++)d[i]=uint8_t((cv(h[2*i])<<4)|cv(h[2*i+1]));return d;}
std::string hex_from_digest(const std::array<uint8_t,32>&d){static const char*h="0123456789abcdef";std::string s;s.reserve(64);for(auto b:d){s.push_back(h[b>>4]);s.push_back(h[b&15]);}return s;}
} // namespace ab
